'use client';

import { useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';
import { useRaf } from '@/hooks/use-raf';
import { useReducedMotion } from '@/hooks/use-reduced-motion';
import { useResizeObserver } from '@/hooks/use-resize-observer';
import { useSmoothPointer } from '@/hooks/use-smooth-pointer';
import { useVisibility } from '@/hooks/use-visibility';
import { hasWebGL, loseContext, pixelRatio } from '@/lib/webgl';
import { BAYER_PLASMA_FRAG, BAYER_PLASMA_VERT } from '@/components/motion/shaders/bayer-plasma-hero';

/* ==========================================================================
   Bayer-Quantised Plasma Hero
   --------------------------------------------------------------------------
   Raw WebGL2 on a single fullscreen triangle. An iterated domain-warped
   plasma is reduced to a small set of grey levels through an 8x8 ordered
   dither matrix derived from gl_FragCoord. The result is a dot-matrix proof of
   itself: newsprint texture instead of a smooth gradient.

   Iteration count is a uniform, not a compile-time constant, so a weak GPU can
   run the same shader at 8 passes instead of 16 without a recompile.
   ========================================================================== */

export interface BayerPlasmaHeroProps {
  /** Plasma warp passes. Clamped to 1..48 — the shader's compiled ceiling. */
  iterations?: number;
  /** How far each pass folds the coordinate through its own sine. */
  warp?: number;
  /** Base spatial frequency of the plasma. */
  frequency?: number;
  /** Radians of rotation applied per pass. */
  rotate?: number;
  /** Contrast pivoted on mid grey, applied before quantisation. */
  contrast?: number;
  /** Ramp exponent the levels are spaced on. */
  gamma?: number;
  /** Number of output grey levels, both ends included. */
  levels?: number;
  /** CSS pixels per dither cell. Scaled by DPR internally. */
  cellSize?: number;
  /** Strength of the elliptical vignette at the optical centre. */
  vignette?: number;
  /** Darkest output colour, linear 0..1 RGB. */
  ink?: readonly [number, number, number];
  /** Lightest output colour, linear 0..1 RGB. */
  paper?: readonly [number, number, number];
  speed?: number;
  maxDpr?: number;
  className?: string;
}

// #region critical
const TRIANGLE = new Float32Array([-1, -1, 3, -1, -1, 3]);
const MAX_ITERATIONS = 48;
const ITERATIONS = 16;
const WARP = 1.5;
const FREQUENCY = 2.2;
const ROTATE = -0.1;
const CONTRAST = 1.35;
const GAMMA = 1.49;
const LEVELS = 11;
const CELL_SIZE = 2;
const VIGNETTE = 0.55;
const INK: readonly [number, number, number] = [0.03, 0.032, 0.038];
const PAPER: readonly [number, number, number] = [0.88, 0.92, 0.9];

interface Gpu {
  gl: WebGL2RenderingContext;
  program: WebGLProgram;
  vao: WebGLVertexArrayObject;
  buffer: WebGLBuffer;
  locations: Map<string, WebGLUniformLocation | null>;
}

function build(gl: WebGL2RenderingContext): Gpu | null {
  const compile = (type: number, src: string): WebGLShader | null => {
    const shader = gl.createShader(type);
    if (!shader) return null;
    gl.shaderSource(shader, src);
    gl.compileShader(shader);
    if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
    console.error('[bayer-plasma-hero]', gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  };

  const vert = compile(gl.VERTEX_SHADER, BAYER_PLASMA_VERT);
  const frag = compile(gl.FRAGMENT_SHADER, BAYER_PLASMA_FRAG);
  const program = gl.createProgram();
  const vao = gl.createVertexArray();
  const buffer = gl.createBuffer();
  if (!vert || !frag || !program || !vao || !buffer) return null;

  gl.attachShader(program, vert);
  gl.attachShader(program, frag);
  gl.linkProgram(program);
  gl.deleteShader(vert);
  gl.deleteShader(frag);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.error('[bayer-plasma-hero]', gl.getProgramInfoLog(program));
    gl.deleteProgram(program);
    return null;
  }

  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, TRIANGLE, gl.STATIC_DRAW);
  const attrib = gl.getAttribLocation(program, 'a_pos');
  if (attrib >= 0) {
    gl.enableVertexAttribArray(attrib);
    gl.vertexAttribPointer(attrib, 2, gl.FLOAT, false, 0, 0);
  }
  gl.bindVertexArray(null);

  return { gl, program, vao, buffer, locations: new Map() };
}

function loc(gpu: Gpu, name: string): WebGLUniformLocation | null {
  const cached = gpu.locations.get(name);
  if (cached !== undefined) return cached;
  const found = gpu.gl.getUniformLocation(gpu.program, name);
  gpu.locations.set(name, found);
  return found;
}

export function BayerPlasmaHero({
  iterations = ITERATIONS,
  warp = WARP,
  frequency = FREQUENCY,
  rotate = ROTATE,
  contrast = CONTRAST,
  gamma = GAMMA,
  levels = LEVELS,
  cellSize = CELL_SIZE,
  vignette = VIGNETTE,
  ink = INK,
  paper = PAPER,
  speed = 1,
  maxDpr = 2,
  className,
}: BayerPlasmaHeroProps) {
  const host = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gpuRef = useRef<Gpu | null>(null);
  const dprRef = useRef(1);

  const { width, height } = useResizeObserver(host);
  const reduced = useReducedMotion();
  const visible = useVisibility();
  const pointer = useSmoothPointer({ target: host, smoothing: 0.03 });
  const [supported, setSupported] = useState(true);

  const paramsRef = useRef({
    iterations, warp, frequency, rotate, contrast, gamma,
    levels, cellSize, vignette, ink, paper, speed,
  });
  paramsRef.current = {
    iterations, warp, frequency, rotate, contrast, gamma,
    levels, cellSize, vignette, ink, paper, speed,
  };

  const drawRef = useRef<(elapsed: number) => void>(() => {});
  drawRef.current = (elapsed: number) => {
    const gpu = gpuRef.current;
    if (!gpu) return;
    const { gl } = gpu;
    const q = paramsRef.current;
    const p = pointer.current;

    gl.useProgram(gpu.program);
    gl.uniform2f(loc(gpu, 'u_resolution'), gl.drawingBufferWidth, gl.drawingBufferHeight);
    gl.uniform1f(loc(gpu, 'u_time'), elapsed * q.speed);
    gl.uniform2f(loc(gpu, 'u_pointer'), p.nx, 1 - p.ny);
    // Clamped to the shader's compiled ceiling: a value above MAX_ITERATIONS
    // would silently do nothing, which is worse than being clamped.
    gl.uniform1i(
      loc(gpu, 'u_iterations'),
      Math.max(1, Math.min(MAX_ITERATIONS, Math.round(q.iterations))),
    );
    gl.uniform1f(loc(gpu, 'u_warp'), q.warp);
    gl.uniform1f(loc(gpu, 'u_freq'), q.frequency);
    gl.uniform1f(loc(gpu, 'u_rotate'), q.rotate);
    gl.uniform1f(loc(gpu, 'u_contrast'), q.contrast);
    gl.uniform1f(loc(gpu, 'u_gamma'), Math.max(0.05, q.gamma));
    gl.uniform1f(loc(gpu, 'u_levels'), Math.max(2, Math.round(q.levels)));
    gl.uniform1f(loc(gpu, 'u_cell'), Math.max(1, q.cellSize * dprRef.current));
    gl.uniform1f(loc(gpu, 'u_vignette'), q.vignette);
    gl.uniform3f(loc(gpu, 'u_ink'), q.ink[0], q.ink[1], q.ink[2]);
    gl.uniform3f(loc(gpu, 'u_paper'), q.paper[0], q.paper[1], q.paper[2]);

    gl.bindVertexArray(gpu.vao);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    gl.bindVertexArray(null);
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    if (!hasWebGL()) {
      setSupported(false);
      return;
    }

    const gl = canvas.getContext('webgl2', {
      antialias: false,
      alpha: false,
      depth: false,
      stencil: false,
      powerPreference: 'high-performance',
    });
    if (!gl) {
      setSupported(false);
      return;
    }

    const gpu = build(gl);
    if (!gpu) {
      loseContext(gl);
      setSupported(false);
      return;
    }
    gpuRef.current = gpu;
    setSupported(true);

    return () => {
      gpuRef.current = null;
      gl.deleteVertexArray(gpu.vao);
      gl.deleteBuffer(gpu.buffer);
      gl.deleteProgram(gpu.program);
      loseContext(gl);
    };
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    const gpu = gpuRef.current;
    if (!canvas || !gpu || width === 0 || height === 0) return;

    const dpr = pixelRatio(maxDpr);
    dprRef.current = dpr;
    const w = Math.max(1, Math.round(width * dpr));
    const h = Math.max(1, Math.round(height * dpr));
    if (canvas.width !== w || canvas.height !== h) {
      canvas.width = w;
      canvas.height = h;
    }
    gpu.gl.viewport(0, 0, w, h);
    // At t = 0 every sine in the warp chain is in phase and the plasma is a
    // near-flat field, so the still frame is taken from a developed moment.
    drawRef.current(reduced ? 7.5 : 0);
  }, [width, height, maxDpr, supported, reduced]);

  const running = supported && visible && !reduced && width > 0 && height > 0;
  useRaf((_dt, elapsed) => drawRef.current(elapsed), running);
  // #endregion critical

  return (
    <div ref={host} className={cn('relative h-full w-full overflow-hidden', className)}>
      {supported ? (
        <canvas ref={canvasRef} className="block h-full w-full" />
      ) : (
        <div
          aria-hidden
          className="h-full w-full bg-bg"
          style={{
            backgroundImage:
              'radial-gradient(circle at 1px 1px, var(--k-line-strong) 1px, transparent 0), radial-gradient(120% 100% at 50% 40%, var(--k-surface) 0%, var(--k-bg) 70%)',
            backgroundSize: '4px 4px, 100% 100%',
          }}
        />
      )}
    </div>
  );
}

/* ==========================================================================
   Bayer-Quantised Plasma — GLSL ES 3.00
   --------------------------------------------------------------------------
   A domain-warped plasma reduced to a small number of grey levels through the
   same 8x8 ordered matrix used by `bayer8-ordered-dither`. The matrix is
   derived from the coordinate rather than sampled from a texture; the full
   derivation is documented in that component's shader file.

   The function is duplicated here on purpose. Each registry item has to
   install standalone via `npx shadcn add`, and a shared GLSL chunk would mean
   a fourth file and a resolution order that shadcn does not guarantee.
   ========================================================================== */

export const BAYER_PLASMA_VERT = `#version 300 es
in vec2 a_pos;
out vec2 v_uv;

void main() {
  v_uv = a_pos * 0.5 + 0.5;
  gl_Position = vec4(a_pos, 0.0, 1.0);
}
`;

export const BAYER_PLASMA_FRAG = `#version 300 es
precision highp float;

in vec2 v_uv;
out vec4 fragColor;

uniform vec2  u_resolution;
uniform float u_time;
uniform vec2  u_pointer;
uniform int   u_iterations;
uniform float u_warp;
uniform float u_freq;
uniform float u_rotate;
uniform float u_contrast;
uniform float u_gamma;
uniform float u_levels;
uniform float u_cell;
uniform float u_vignette;
uniform vec3  u_ink;
uniform vec3  u_paper;

/* A constant upper bound, with a uniform-driven 'break'. A fully dynamic loop
   bound is legal in ES 3.00 but stops the compiler bounding register pressure,
   and some mobile drivers respond by recompiling the shader whenever the
   uniform changes — a visible hitch at exactly the moment you lower the
   quality setting to avoid one. */
const int MAX_ITERATIONS = 48;

vec2 rot(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return mat2(c, -s, s, c) * p;
}

/* Iterated domain warp. Each pass rotates the coordinate, folds it through the
   sine of its own transpose ('p.yx', not 'p.xy' — swapping the components is
   what couples the axes and produces marbling instead of stripes), and
   accumulates a wave. The per-iteration phase offset 'float(i) * 0.7'
   decorrelates the passes; without it every iteration warps in lockstep and
   the result is a plain ripple. */
float plasma(vec2 uv, float t) {
  vec2 p = uv * u_freq;
  float value = 0.0;
  float amp = 1.0;
  float norm = 0.0;

  for (int i = 0; i < MAX_ITERATIONS; i++) {
    if (i >= u_iterations) break;
    p = rot(p, u_rotate);
    p += u_warp * sin(p.yx * 1.31 + t + float(i) * 0.7) / (1.0 + float(i) * 0.35);
    value += amp * sin(p.x + p.y + t * 0.6);
    norm += amp;
    amp *= 0.86;
  }

  /* Divide by the amplitude actually accumulated, not by a hard-coded
     constant. Otherwise dropping from 21 iterations to 8 for a weak GPU also
     drops the exposure, and the low-quality path renders visibly darker. */
  return value / max(norm, 1e-4);
}

float bayer8(vec2 cellCoord) {
  ivec2 c = ivec2(floor(cellCoord));
  int x = c.x & 7;
  int y = c.y & 7;
  int v = 32 * ((x & 1) ^ (y & 1))
        + 16 * (y & 1)
        +  8 * (((x >> 1) & 1) ^ ((y >> 1) & 1))
        +  4 * ((y >> 1) & 1)
        +  2 * (((x >> 2) & 1) ^ ((y >> 2) & 1))
        +       ((y >> 2) & 1);
  return float(v) / 64.0;
}

/* An elliptical vignette centred at (0.5, 0.4) — the OPTICAL centre, roughly
   where the eye expects the middle of a frame to be, not the geometric one.
   Centring it at 0.5 makes a hero read as slightly bottom-heavy. */
float heroVignette(vec2 uv, float aspect) {
  vec2 d = uv - vec2(0.5, 0.4);
  d.x *= aspect;
  float r = length(d * vec2(0.82, 1.25));
  return 1.0 - u_vignette * smoothstep(0.18, 0.92, r);
}

void main() {
  float aspect = u_resolution.x / max(u_resolution.y, 1.0);

  vec2 p = v_uv - 0.5;
  p.x *= aspect;

  /* The pointer nudges the plasma's own coordinate space rather than adding a
     highlight, so the field appears to lean into the cursor. */
  vec2 m = (u_pointer - 0.5) * vec2(aspect, 1.0);
  float lum = plasma(p + m * 0.12, u_time * 0.35) * 0.5 + 0.5;

  lum = clamp((lum - 0.5) * u_contrast + 0.5, 0.0, 1.0);
  lum *= heroVignette(v_uv, aspect);

  /* Quantise on a gamma-spaced ramp. The reference implementation carried an
     11-entry grey table and found the nearest entry with a branchless ladder
     of ten mix/step pairs. A monotone ramp collapses that whole search into
     encode, round, decode — and the dither offset has to be applied in the
     ENCODED space, or the perturbation is the wrong size in the shadows. */
  float steps = max(u_levels - 1.0, 1.0);
  float threshold = bayer8(gl_FragCoord.xy / max(u_cell, 1.0));
  float encoded = pow(lum, 1.0 / u_gamma);
  encoded = clamp(encoded + (threshold - 0.5) / steps, 0.0, 1.0);
  float quantised = pow(floor(encoded * steps + 0.5) / steps, u_gamma);

  fragColor = vec4(mix(u_ink, u_paper, quantised), 1.0);
}
`;
